## Why This Is Asked
This question tests mastery of advanced data structure design by combining segment trees with multisets to handle weighted intervals with duplicate support. It also evaluates understanding of binary search applied to aggregated data structures for kth largest queries.

## Key Concepts
- **Coordinate compression** on endpoints to discretize the domain
- **Segment tree** where each node stores a multiset of weights for intervals covering that node's range
- **Interval decomposition** into O(log n) nodes for efficient updates
- **Path aggregation** for point sum queries
- **Binary search over weight values** with counts from multisets to support kthLargest queries

## Code Example
```javascript
class IntervalDS {
  constructor(coords) {
    this.coords = coords;
    this.N = coords.length;
    this.tree = Array(4 * this.N).fill(null).map(() => new Map());
    this.sums = Array(4 * this.N).fill(0);
  }

  insert(l, r, w) {
    this.update(1, 0, this.N - 1, l, r, w, 1);
  }

  erase(l, r, w) {
    this.update(1, 0, this.N - 1, l, r, w, -1);
  }

  update(node, start, end, l, r, w, delta) {
    if (r < start || end < l) return;
    if (l <= start && end <= r) {
      const count = this.tree[node].get(w) || 0;
      this.tree[node].set(w, count + delta);
      if (this.tree[node].get(w) === 0) this.tree[node].delete(w);
      this.sums[node] += w * delta;
      return;
    }
    const mid = Math.floor((start + end) / 2);
    this.update(node * 2, start, mid, l, r, w, delta);
    this.update(node * 2 + 1, mid + 1, end, l, r, w, delta);
    this.sums[node] = this.sums[node * 2] + this.sums[node * 2 + 1];
  }

  sumAtPoint(x) {
    return this.querySum(1, 0, this.N - 1, x);
  }

  querySum(node, start, end, x) {
    if (x < start || x > end) return 0;
    if (start === end) return this.sums[node];
    const mid = Math.floor((start + end) / 2);
    return this.sums[node] + 
      (x <= mid ? this.querySum(node * 2, start, mid, x) 
                : this.querySum(node * 2 + 1, mid + 1, end, x));
  }

  kthLargest(x, k) {
    const weights = [...new Set(this.getWeightsAtPoint(x))].sort((a, b) => b - a);
    if (k > weights.length) return null;
    return weights[k - 1];
  }

  getWeightsAtPoint(x) {
    const result = [];
    this.collectWeights(1, 0, this.N - 1, x, result);
    return result;
  }

  collectWeights(node, start, end, x, result) {
    if (x < start || x > end) return;
    for (const [w, count] of this.tree[node]) {
      result.push(...Array(count).fill(w));
    }
    if (start === end) return;
    const mid = Math.floor((start + end) / 2);
    this.collectWeights(node * 2, start, mid, x, result);
    this.collectWeights(node * 2 + 1, mid + 1, end, x, result);
  }
}
```

## Why This Is Asked
This question tests mastery of maintaining order statistics with dynamic updates, handling duplicates efficiently, and implementing lazy deletion—all while achieving O(log n) time complexity.

## Key Concepts
- **Two heaps for median maintenance**: A max-heap stores the lower half, while a min-heap stores the upper half, allowing O(1) median retrieval
- **Duplicate handling**: Store actual values in heaps with a frequency counter map to track occurrences
- **Lazy deletion**: Defer removals by updating a delayed-delete map; prune elements lazily when they surface at heap tops to achieve O(log n) amortized erase

## Code Example
```python
import heapq

class DualHeap:
    def __init__(self):
        self.small = []  # max-heap (store negatives)
        self.large = []  # min-heap
        self.delayed = {}  # lazy deletion map
        self.small_size = 0
        self.large_size = 0

    def prune(self, heap):
        while heap:
            num = -heap[0] if heap is self.small else heap[0]
            if self.delayed.get(num, 0) > 0:
                heapq.heappop(heap)
                self.delayed[num] -= 1
                if self.delayed[num] == 0:
                    del self.delayed[num]
            else:
                break

    def rebalance(self):
        if self.small_size > self.large_size + 1:
            val = -heapq.heappop(self.small)
            self.small_size -= 1
            heapq.heappush(self.large, val)
            self.large_size += 1
        elif self.large_size > self.small_size + 1:
            val = heapq.heappop(self.large)
            self.large_size -= 1
            heapq.heappush(self.small, -val)
            self.small_size += 1

    def insert(self, num):
        if not self.small or num <= -self.small[0]:
            heapq.heappush(self.small, -num)
            self.small_size += 1
        else:
            heapq.heappush(self.large, num)
            self.large_size += 1
        self.rebalance()

    def erase(self, num):
        self.delayed[num] = self.delayed.get(num, 0) + 1
        if num <= -self.small[0]:
            self.small_size -= 1
        else:
            self.large_size -= 1
        self.rebalance()

    def getMedian(self):
        if self.small_size > self.large_size:
            self.prune(self.small)
            return -self.small[0]
        elif self.large_size > self.small_size:
            self.prune(self.large)
            return self.large[0]
        return (-self.small[0] + self.large[0]) / 2
```

